1088	            const contactForm = document.getElementById('contact-form');
1089	            if (contactForm) {
1090	                const showError = (field, message) => {
1091	                    const fieldGroup = field.closest('.form-group');
1092	                    const error = fieldGroup.querySelector('.field-error');
1093	                    if (error) {
1094	                        error.classList.add('show');
1095	                        error.textContent = message;
1096	                        error.setAttribute('role', 'alert');
1097	                    }
