1119	                    }
1120	
1121	                    if (!field.checkValidity()) {
1122	                        let message = 'Invalid input';
1123	                        if (field.type === 'email') {
1124	                            message = 'Please enter a valid email address. Example: jane@example.com';
1125	                        } else if (field.id === 'name') {
1126	                            if (field.value.length < 2) {
1127	                                message = 'Name must be at least 2 characters';
1128	                            } else if (!/^[A-Za-z\s]+$/.test(field.value)) {
