1199	                            firstError.focus();
1200	                        }
1201	                        return;
1202	                    }
1203	
1204	                    const submitBtn = document.getElementById('submit-btn');
1205	                    isSubmitting = true;
1206	                    submitBtn.disabled = true;
1207	                    submitBtn.classList.add('loading');
1208	                    const originalHTML = submitBtn.innerHTML;
