1221	                        signal: controller.signal
1222	                    })
1223	                    .then(response => {
1224	                        if (!response.ok) {
1225	                            if (response.status === 429) {
1226	                                throw new Error('Too many requests. Please wait a moment and try again.');
1227	                            } else if (response.status >= 500) {
1228	                                throw new Error('Server is temporarily unavailable. Please try again later.');
1229	                            } else if (response.status >= 400) {
1230	                                throw new Error(`Request error (${response.status}). Please check your input and try again.`);
1231	                            }
1232	                            throw new Error(`Server error: ${response.status}`);
1233	                        }
1234	                        return response;
1235	                    })
1236	                    .then(() => {
1237	                        feedback.className = 'form-feedback success';
